<?php require __DIR__.'/bootstrap.php';require_permission('backups.manage');$pdo=db();$error='';$dir=ROOT_DIR.'/uploads/backups';if(!is_dir($dir))@mkdir($dir,0755,true);$tables=['site_content','settings','services','gallery','service_areas','tips','correo_tipo','correo','api_integrations','site_sections','media_library'];
function backup_dataset(PDO $pdo,array $tables):array{$data=['version'=>2,'created_at'=>date('c'),'tables'=>[]];foreach($tables as $t)$data['tables'][$t]=$pdo->query("SELECT * FROM `$t`")->fetchAll();return $data;}
function create_full_backup(PDO $pdo,array $tables,string $dir):array{if(!class_exists('ZipArchive'))throw new RuntimeException('PHP ZipArchive is required for full backups. Enable the zip extension in hosting PHP settings.');$name='castros-ready-backup-'.date('Ymd-His').'.zip';$full=$dir.'/'.$name;$zip=new ZipArchive();if($zip->open($full,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)throw new RuntimeException('Could not create backup ZIP.');$zip->addFromString('database.json',json_encode(backup_dataset($pdo,$tables),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));$uploadRoot=ROOT_DIR.'/uploads';if(is_dir($uploadRoot)){$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($uploadRoot,FilesystemIterator::SKIP_DOTS));foreach($it as $file){if(!$file->isFile())continue;$real=$file->getPathname();if(str_starts_with($real,$dir.DIRECTORY_SEPARATOR))continue;$rel='uploads/'.str_replace('\\','/',substr($real,strlen($uploadRoot)+1));$zip->addFile($real,$rel);}}$zip->close();return [$name,'uploads/backups/'.$name];}
function restore_full_backup(PDO $pdo,array $tables,string $zipPath):void{if(!class_exists('ZipArchive'))throw new RuntimeException('PHP ZipArchive is required to restore this backup.');$zip=new ZipArchive();if($zip->open($zipPath)!==true)throw new RuntimeException('Could not open backup ZIP.');$json=$zip->getFromName('database.json');$data=$json!==false?json_decode($json,true):null;if(!is_array($data['tables']??null)){$zip->close();throw new RuntimeException('Backup database payload is invalid.');}$pdo->beginTransaction();try{foreach($tables as $t){if(!array_key_exists($t,$data['tables']))continue;$pdo->exec("DELETE FROM `$t`");foreach($data['tables'][$t] as $row){if(!$row)continue;$cols=array_keys($row);$sql="INSERT INTO `$t` (`".implode('`,`',$cols)."`) VALUES (".implode(',',array_fill(0,count($cols),'?')).")";$pdo->prepare($sql)->execute(array_values($row));}}$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$zip->close();throw $e;}for($i=0;$i<$zip->numFiles;$i++){$name=$zip->getNameIndex($i);if(!is_string($name)||!str_starts_with($name,'uploads/')||str_contains($name,'../')||str_starts_with($name,'uploads/backups/'))continue;$target=ROOT_DIR.'/'.$name;if(str_ends_with($name,'/')){if(!is_dir($target))@mkdir($target,0755,true);continue;}$parent=dirname($target);if(!is_dir($parent))@mkdir($parent,0755,true);$stream=$zip->getStream($name);if($stream){$out=fopen($target,'wb');if($out){stream_copy_to_stream($stream,$out);fclose($out);}fclose($stream);}}$zip->close();}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';try{if($a==='create'){[$name,$rel]=create_full_backup($pdo,$tables,$dir);$pdo->prepare('INSERT INTO site_backups(backup_name,file_path,created_by) VALUES(?,?,?)')->execute([$name,$rel,(int)$_SESSION['cr_admin_id']]);log_activity('backup_create','Created full website backup',['file'=>$name]);flash('success','Full backup created with database content and uploaded files.');}elseif($a==='restore'){$id=(int)($_POST['id']??0);$st=$pdo->prepare('SELECT * FROM site_backups WHERE id=?');$st->execute([$id]);$b=$st->fetch();if(!$b)throw new RuntimeException('Backup not found.');restore_full_backup($pdo,$tables,ROOT_DIR.'/'.$b['file_path']);log_activity('backup_restore','Restored full website backup',['backup_id'=>$id]);admin_notify('warning','Backup restored','A full website backup was restored.','backups.php');flash('success','Backup restored successfully.');}elseif($a==='delete'){$id=(int)($_POST['id']??0);$st=$pdo->prepare('SELECT file_path FROM site_backups WHERE id=?');$st->execute([$id]);$fp=$st->fetchColumn();if($fp&&is_file(ROOT_DIR.'/'.$fp))@unlink(ROOT_DIR.'/'.$fp);$pdo->prepare('DELETE FROM site_backups WHERE id=?')->execute([$id]);log_activity('backup_delete','Deleted website backup',['backup_id'=>$id]);flash('success','Backup deleted.');}header('Location: backups.php');exit;}catch(Throwable $e){$error=$e->getMessage();}}
$rows=$pdo->query('SELECT * FROM site_backups ORDER BY id DESC')->fetchAll();$pageTitle='Backup & Restore';$active='backups';require __DIR__.'/_header.php';?><div class="page-heading"><div><p class="eyebrow">BACKUP & RESTORE</p><h1>Protect website content</h1><p class="muted">Create a ZIP restore point containing CMS data and uploaded images before important changes.</p></div><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="create"><button>Create full backup now</button></form></div><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?><div class="backup-grid"><?php if(!$rows):?><div class="empty-state"><strong>No backups yet</strong><p>Create a restore point before making major site changes.</p></div><?php endif;foreach($rows as $b):?><article class="backup-card"><div><span><?=icon('dashboard')?></span><strong><?=h($b['backup_name'])?></strong><small><?=h($b['created_at'])?></small></div><div class="actions"><a class="button secondary small" href="../<?=h($b['file_path'])?>" download>Download ZIP</a><form method="post" data-swal-confirm="Restore this backup?" data-swal-text="Current CMS data and uploaded images may be replaced by this restore point."><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="restore"><input type="hidden" name="id" value="<?=$b['id']?>"><button class="button small">Restore</button></form><form method="post" data-swal-confirm="Delete this backup?" data-swal-text="This backup ZIP will be permanently removed."><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$b['id']?>"><button class="button danger-lite small">Delete</button></form></div></article><?php endforeach;?></div><?php require __DIR__.'/_footer.php';